################################################################################
#
#  RieSrf/Endomorphisms/Algebraization.jl : recognizing algebraic numbers
#
#  Recognition of complex numbers (balls) as elements of a number field, of
#  their minimal polynomials over a number field, and of the number field
#  generated by several of them, with LLL (integral_left_kernel). Heuristic:
#  a result is accepted if it is consistent with the balls.
#
#  Entry points: algebraize_element, approximate_minimal_polynomial,
#  approximate_number_field.
#
################################################################################

@doc raw"""
    algebraize_element(a_CC::AcbFieldElem, K::NumField, v::Union{PosInf, InfPlc} = infinite_places(K)[1])
      -> NumFieldElem

Recognize the complex number `a_CC` as an element of the number field K,
embedded into CC by the place v. Throws an error if none is found.
"""
function algebraize_element(a_CC::AcbFieldElem, K::NumField, v::Union{PosInf, InfPlc} = infinite_places(K)[1])
  CC = parent(a_CC)
  prec = precision(CC)
  genK = gen(K)
  v = v.embedding

  degK = degree(K)
  M = [ CC(_embed_coefficient(genK^i, v, prec)) for i in (0:(degK - 1)) ]
  push!(M, -a_CC)
  M = transpose(matrix(CC,[M]))

  Ker, test_ker = integral_left_kernel(M)
  row = Ker[1,:] 
  den = row[end]

  if den != 0
    a = sum([ row[i + 1]*genK^i for i in (0:(degK - 1)) ]) //den
    if contains(a_CC, evaluate(a, v, prec))
        return a
    end
  end
  error("No element found.")
end

@doc raw"""
    approximate_minimal_polynomial(a_CC::AcbFieldElem, K::NumField, v::Union{PosInf, InfPlc},
                                   lower_bound::Int = 1, upper_bound::Int = 16,
                                   degree_divides::Int = -1) -> PolyRingElem

Recognize the minimal polynomial over K (embedded into CC by the place v) of
the complex number `a_CC`: the polynomials of degree 1, 2, ..., `upper_bound`
are tried in turn (only degrees dividing `degree_divides` if that is given).
`lower_bound` is not used at the moment. Throws an error if none is found.
"""
function approximate_minimal_polynomial(a_CC::AcbFieldElem, K::NumField, v::Union{PosInf, InfPlc}, 
  lower_bound::Int= 1, upper_bound::Int= 16, degree_divides::Int= -1)
  degK = degree(K)
  R, x = polynomial_ring(K)
  genK =  gen(K) 
  CC = parent(a_CC)
  prec = precision(CC)
  RR = ArbField(prec)

  powersgenCC = [ CC(_embed_coefficient(genK^i, v.embedding, prec)) for i in (0:(degK - 1)) ]

  poweraCCsc = 1 
  degf = 0
  MLine = [ powergenCC * poweraCCsc for powergenCC in powersgenCC ]

  while degf < upper_bound
    degf += 1
    poweraCCsc *= a_CC
    MLine = vcat(MLine,  [ powergenCC * poweraCCsc for powergenCC in powersgenCC ])
    M = transpose(matrix(CC, [MLine] ))
    test = degree_divides == -1
    if !test
      test = mod(degree_divides, degf) == 0
    end
    if test
      Ker, test_ker = integral_left_kernel(M)

      if test_ker
        row = Ker[1,:]
        f = sum([ sum([ row[i*degK + j + 1]*genK^j for j in (0:(degK - 1)) ]) * x^i for i in (0:degf) ])
        f /= leading_coefficient(f)
        f_CC = _embed_poly(f, v, prec)

        # accepted if a_CC is a root (heuristic)
        if contains(f_CC(a_CC), zero(CC))
            return f
        end
      end
    end
  end
  error("Failed to find minimal polynomial using LLL. Try increasing the precision.")
end


@doc raw"""
    approximate_number_field(aCCs::Vector{AcbFieldElem}, K::NumField, v::Union{PosInf, InfPlc},
                             upper_bound::Int = 16, degree_divides::Int = -1)
      -> NumField, Vector{NumFieldElem}, Union{PosInf, InfPlc}, NumFieldHom

Recognize the complex numbers `aCCs` as elements of an extension L of K
(embedded into CC by the place v), adjoining them one at a time (the
smallest such L, if the recognition succeeds). Returns L, the elements of L
corresponding to `aCCs`, the place of L extending v under which they are the
`aCCs`, and the inclusion K -> L. `upper_bound` and `degree_divides` as for
`approximate_minimal_polynomial`.
"""
function approximate_number_field(aCCs::Vector{AcbFieldElem}, K::NumField, v::Union{PosInf, InfPlc},  
  upper_bound::Int= 16, degree_divides::Int= -1)
  L = K
  h = identity_map(K)
  isempty(aCCs) && return L, elem_type(K)[], v, h

  tupsa = []
  for aCC in aCCs
    Lnew, tupsa, v, hnew = extend_number_field_step(L, tupsa, v, aCC, upper_bound, degree_divides)
    if Lnew != L 
      h = h*hnew
    end
    L = Lnew
  end
  return L, [ tupa[1] for tupa in tupsa ], v,  h
end

# One step of approximate_number_field: adjoin anewCC to K (if it is not in
# K already). tupsa: the pairs (element, complex value) recognized so far,
# moved to the new field.
function extend_number_field_step(K, tupsa, v, anewCC, upper_bound=16, degree_divides =-1)
  #Determine min_poly over K
  gK = approximate_minimal_polynomial(anewCC, K, v, 1, upper_bound, degree_divides)
  
  CC = parent(anewCC)
  #Case where the min_poly has degree 1
  if degree(gK) == 1 
    anew = -coeff(gK, 0)/coeff(gK, 1)
    push!(tupsa, (anew, anewCC))
    return K, tupsa, v, identity_map(K)
  end

  L_rel, a = number_field(gK)
  L, h = absolute_simple_field(L_rel)
  hm = inv(h)

  anew = hm(a)
  f = minimal_polynomial(gen(K))
  R_L, t = polynomial_ring(L)
  f_L = sum([ hm(L_rel(coeff(f, i)))*t^i for i in (0:(degree(f))) ])
  # the embedding of K into L, and an embedding of L extending v under which
  # the new element has the value anewCC (try all images of the generator of K)
  for rt_f in roots(f_L)
    phi = hom(K, L, rt_f)
    for w in extend(v.embedding, phi)
      if contains(anewCC - w(anew), zero(CC))
        tupsa = [ (phi(tupa[1]), tupa[2]) for tupa in tupsa ]
        push!(tupsa, (anew, anewCC))
        return L, tupsa, infinite_place(w), phi
      end
    end
  end
  error("Could not extend number field.")
end